\label{capball}
For sufficiently small $\delta$ and $\epsilon<1/200$, the surgery cap lies in
\[
  B_{\widetilde g}
  \bigl(p_0,R(x_0)^{-1/2}(A_0+5)\bigr)
\]
and contains
\[
  B_{\widetilde g}
  \bigl(p_0,R(x_0)^{-1/2}(A_0+3)\bigr).
\]
The complement of its closure is isometric to $N^-$.
\end{lemma}

